+const form = document.getElementById('contactForm');
+const fullNameInput = document.getElementById('fullName');
+const emailInput = document.getElementById('email');
+const phoneInput = document.getElementById('phone');
+
+const fullNameError = document.getElementById('fullNameError');
+const emailError = document.getElementById('emailError');
+const phoneError = document.getElementById('phoneError');
+
+const validationState = {
+    fullName: false,
+    email: false,
+    phone: true
+};
+
+function validateFullName(value) {
+    const trimmed = value.trim();
+    return trimmed.length > 0;
+}
+
+function validateEmail(value) {
+    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+    return emailRegex.test(value.trim());
+}
+
+function validatePhone(value) {
+    if (value.trim() === '') {
+        return true;
+    }
+    const phoneRegex = /^[\d\s\-().+]+$/;
+    return phoneRegex.test(value.trim()) && value.replace(/\D/g, '').length >= 10;
+}
+
+function showError(field, errorElement, message) {
+    field.classList.add('error');
+    errorElement.textContent = message;
+    errorElement.classList.add('show');
+}
+
+function clearError(field, errorElement) {
+    field.classList.remove('error');
+    errorElement.textContent = '';
+    errorElement.classList.remove('show');
+}
+
+fullNameInput.addEventListener('blur', () => {
+    if (fullNameInput.value.trim() === '') {
+        showError(fullNameInput, fullNameError, 'Full name is required');
+        validationState.fullName = false;
+    } else if (!validateFullName(fullNameInput.value)) {
+        showError(fullNameInput, fullNameError, 'Please enter a valid full name');
+        validationState.fullName = false;
+    } else {
+        clearError(fullNameInput, fullNameError);
+        validationState.fullName = true;
+    }
+});
+
+fullNameInput.addEventListener('input', () => {
+    if (fullNameInput.value.trim() !== '' && validateFullName(fullNameInput.value)) {
+        clearError(fullNameInput, fullNameError);
+        validationState.fullName = true;
+    }
+});
+
+emailInput.addEventListener('blur', () => {
+    if (emailInput.value.trim() === '') {
+        showError(emailInput, emailError, 'Email address is required');
+        validationState.email = false;
+    } else if (!validateEmail(emailInput.value)) {
+        showError(emailInput, emailError, 'Please enter a valid email address');
+        validationState.email = false;
+    } else {
+        clearError(emailInput, emailError);
+        validationState.email = true;
+    }
+});
+
+emailInput.addEventListener('input', () => {
+    if (emailInput.value.trim() !== '' && validateEmail(emailInput.value)) {
+        clearError(emailInput, emailError);
+        validationState.email = true;
+    }
+});
+
+phoneInput.addEventListener('blur', () => {
+    if (phoneInput.value.trim() === '') {
+        clearError(phoneInput, phoneError);
+        validationState.phone = true;
+    } else if (!validatePhone(phoneInput.value)) {
+        showError(phoneInput, phoneError, 'Please enter a valid phone number');
+        validationState.phone = false;
+    } else {
+        clearError(phoneInput, phoneError);
+        validationState.phone = true;
+    }
+});
+
+phoneInput.addEventListener('input', () => {
+    if (phoneInput.value.trim() === '' || validatePhone(phoneInput.value)) {
+        clearError(phoneInput, phoneError);
+    }
+});
+
+form.addEventListener('submit', (e) => {
+    e.preventDefault();
+
+    let hasErrors = false;
+
+    if (!validateFullName(fullNameInput.value)) {
+        showError(fullNameInput, fullNameError, 'Full name is required');
+        validationState.fullName = false;
+        hasErrors = true;
+    } else {
+        clearError(fullNameInput, fullNameError);
+        validationState.fullName = true;
+    }
+
+    if (!validateEmail(emailInput.value)) {
+        showError(emailInput, emailError, emailInput.value.trim() === '' ? 'Email address is required' : 'Please enter a valid email address');
+        validationState.email = false;
+        hasErrors = true;
+    } else {
+        clearError(emailInput, emailError);
+        validationState.email = true;
+    }
+
+    if (!validatePhone(phoneInput.value)) {
+        showError(phoneInput, phoneError, 'Please enter a valid phone number');
+        validationState.phone = false;
+        hasErrors = true;
+    } else {
+        clearError(phoneInput, phoneError);
+        validationState.phone = true;
+    }
+
+    if (!hasErrors) {
+        const formData = {
+            fullName: fullNameInput.value.trim(),
+            email: emailInput.value.trim(),
+            phone: phoneInput.value.trim()
+        };
+        console.log('Form submitted successfully:', formData);
+        form.reset();
+    }
+});
+
